BEGIN;
CREATE TABLE hr_assets(id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,company_id TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,branch_id TEXT REFERENCES branches(id) ON DELETE SET NULL,asset_type TEXT NOT NULL,name TEXT NOT NULL,asset_tag TEXT,serial_number TEXT,status TEXT NOT NULL DEFAULT 'AVAILABLE' CHECK(status IN('AVAILABLE','ASSIGNED','MAINTENANCE','RETIRED','LOST')),created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(tenant_id,asset_tag));
CREATE TABLE hr_asset_assignments(id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,asset_id TEXT NOT NULL REFERENCES hr_assets(id) ON DELETE RESTRICT,staff_id TEXT NOT NULL REFERENCES staff(id) ON DELETE CASCADE,assigned_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,acknowledged_at TIMESTAMP(3),returned_at TIMESTAMP(3),condition_out TEXT,condition_in TEXT,assigned_by TEXT,CHECK(returned_at IS NULL OR returned_at>=assigned_at));
CREATE UNIQUE INDEX hr_asset_active_assignment_uq ON hr_asset_assignments(asset_id) WHERE returned_at IS NULL;
CREATE INDEX hr_asset_staff_open_idx ON hr_asset_assignments(tenant_id,staff_id,returned_at);
CREATE TABLE hr_policies(id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,company_id TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,title TEXT NOT NULL,category TEXT,version TEXT NOT NULL,content_ref TEXT,mandatory BOOLEAN NOT NULL DEFAULT TRUE,published_at TIMESTAMP(3),active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(tenant_id,company_id,title,version));
CREATE TABLE hr_policy_acknowledgements(id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,policy_id TEXT NOT NULL REFERENCES hr_policies(id) ON DELETE RESTRICT,staff_id TEXT NOT NULL REFERENCES staff(id) ON DELETE CASCADE,acknowledged_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,evidence TEXT,UNIQUE(policy_id,staff_id));
CREATE TABLE hr_safety_records(id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,company_id TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,branch_id TEXT NOT NULL REFERENCES branches(id) ON DELETE RESTRICT,staff_id TEXT REFERENCES staff(id) ON DELETE SET NULL,record_type TEXT NOT NULL CHECK(record_type IN('SAFETY_TRAINING','HEALTH_EXAM','WORK_ACCIDENT','SAFETY_CERTIFICATION','INCIDENT_FOLLOWUP')),title TEXT NOT NULL,occurred_on DATE,expires_on DATE,status TEXT NOT NULL DEFAULT 'OPEN',restricted BOOLEAN NOT NULL DEFAULT TRUE,document_id TEXT,notes TEXT,created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX hr_safety_expiry_idx ON hr_safety_records(tenant_id,company_id,expires_on,status);
CREATE TABLE hr_action_items(id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,company_id TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,branch_id TEXT REFERENCES branches(id) ON DELETE CASCADE,item_type TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,title TEXT NOT NULL,priority TEXT NOT NULL DEFAULT 'NORMAL' CHECK(priority IN('LOW','NORMAL','HIGH','CRITICAL')),due_at TIMESTAMP(3),assignee_id TEXT,status TEXT NOT NULL DEFAULT 'OPEN' CHECK(status IN('OPEN','IN_PROGRESS','DONE','DISMISSED')),dedupe_key TEXT,created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,completed_at TIMESTAMP(3));
CREATE UNIQUE INDEX hr_action_items_dedupe_uq ON hr_action_items(tenant_id,dedupe_key) WHERE dedupe_key IS NOT NULL;
CREATE INDEX hr_action_items_inbox_idx ON hr_action_items(tenant_id,company_id,status,priority,due_at);
CREATE TABLE hr_domain_events(id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,company_id TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,branch_id TEXT REFERENCES branches(id) ON DELETE SET NULL,event_type TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,payload JSONB NOT NULL DEFAULT '{}'::jsonb,idempotency_key TEXT NOT NULL,occurred_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,processed_at TIMESTAMP(3),UNIQUE(tenant_id,idempotency_key));
CREATE INDEX hr_domain_events_pending_idx ON hr_domain_events(tenant_id,company_id,processed_at,occurred_at);
COMMIT;
